import Link from "next/link";
import type { ReactNode } from "react";
import { Container } from "@/components/container";
import { ItemCard } from "@/components/item-card";
import { PageShell } from "@/components/page-shell";
import { SectionHeading } from "@/components/section-heading";
import { experience } from "@/data/experience";
import { projects } from "@/data/projects";
import { research } from "@/data/research";
import { siteConfig } from "@/data/site";
import { writing } from "@/data/writing";

export default function Home() {
  const featuredProjects = projects.slice(0, 2);
  const featuredResearch = research.slice(0, 2);
  const featuredWriting = writing.slice(0, 2);
  const currentExperience = experience[0];

  return (
    <PageShell>
      <section className="border-b border-line py-20 sm:py-28">
        <Container>
          <div className="grid gap-12 lg:grid-cols-[1fr_360px] lg:items-end">
            <div>
              <p className="font-mono text-xs font-medium uppercase tracking-[0.18em] text-accent">
                {siteConfig.role}
              </p>
              <h1 className="mt-6 max-w-4xl text-5xl font-semibold tracking-normal text-foreground sm:text-6xl">
                {siteConfig.name}
              </h1>
              <p className="mt-6 max-w-2xl text-lg leading-8 text-muted">
                {siteConfig.summary}
              </p>
              <div className="mt-8 flex flex-wrap gap-3">
                <Link
                  href="/projects"
                  className="rounded-md bg-foreground px-4 py-2.5 text-sm font-medium text-background transition hover:opacity-85"
                >
                  View projects
                </Link>
                <Link
                  href="/contact"
                  className="rounded-md border border-line bg-panel px-4 py-2.5 text-sm font-medium transition hover:border-foreground"
                >
                  Get in touch
                </Link>
              </div>
            </div>
            <aside className="rounded-lg border border-line bg-panel p-5">
              <p className="font-mono text-xs uppercase tracking-[0.16em] text-muted">
                Current focus
              </p>
              <p className="mt-4 text-sm leading-6 text-muted">
                {siteConfig.availability}
              </p>
              {currentExperience ? (
                <div className="mt-6 border-t border-line pt-5">
                  <p className="text-sm font-medium">{currentExperience.role}</p>
                  <p className="mt-1 text-sm text-muted">{currentExperience.company}</p>
                </div>
              ) : null}
            </aside>
          </div>
        </Container>
      </section>

      <section className="py-14">
        <Container>
          <SectionHeading
            title="Selected projects"
            description="Product, infrastructure, and research-facing systems."
            action={<TextLink href="/projects">All projects</TextLink>}
          />
          <div className="grid gap-4 md:grid-cols-2">
            {featuredProjects.map((project) => (
              <ItemCard
                key={project.title}
                title={project.title}
                eyebrow={project.year}
                summary={project.summary}
                href={project.href}
                tags={project.stack}
              />
            ))}
          </div>
        </Container>
      </section>

      <section className="border-y border-line bg-panel-muted py-14">
        <Container>
          <SectionHeading
            title="Research"
            description="Papers, reports, benchmarks, and technical investigations."
            action={<TextLink href="/research">All research</TextLink>}
          />
          <div className="grid gap-4 md:grid-cols-2">
            {featuredResearch.map((item) => (
              <ItemCard
                key={item.title}
                title={item.title}
                eyebrow={item.venue ?? item.date}
                summary={item.summary}
                href={item.href ?? item.pdf}
                tags={item.tags}
              />
            ))}
          </div>
        </Container>
      </section>

      <section className="py-14">
        <Container>
          <SectionHeading
            title="Writing"
            description="Notes on engineering, systems, research, and product judgment."
            action={<TextLink href="/writing">All writing</TextLink>}
          />
          <div className="grid gap-4 md:grid-cols-2">
            {featuredWriting.map((item) => (
              <ItemCard
                key={item.title}
                title={item.title}
                eyebrow={item.publication ?? item.date}
                summary={item.summary}
                href={item.href}
                tags={item.tags}
              />
            ))}
          </div>
        </Container>
      </section>
    </PageShell>
  );
}

function TextLink({ href, children }: { href: string; children: ReactNode }) {
  return (
    <Link href={href} className="text-sm font-medium text-accent hover:underline">
      {children}
    </Link>
  );
}
